Let $S$ be a scheme. Consider a separated \'etale morphism
$f : V \to W$ of algebraic spaces over $S$.
Assume there exists a
closed subspace $T \subset W$ such that $f^{-1}T \to T$ is
an isomorphism. Then, with $W^0 = W \setminus T$ and
$V^0 = f^{-1}W^0$ the base change functor
$$
\left\{
\begin{matrix}
g : X \to W\text{ morphism of algebraic spaces} \\
g^{-1}(W^0) \to W^0\text{ is an isomorphism}
\end{matrix}
\right\}
\longrightarrow
\left\{
\begin{matrix}
h : Y \to V\text{ morphism of algebraic spaces} \\
h^{-1}(V^0) \to V^0\text{ is an isomorphism}
\end{matrix}
\right\}
$$
is an equivalence of categories.

statement:
Let $\mathcal{X}$ be an algebraic stack.
\begin{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module
with the flat base change property on $\mathcal{X}_\etale$.
The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g : \Sh(\mathcal{X}_{lisse,\etale}) \to
\Sh(\mathcal{X}_\etale)$ is as in Lemma \ref{lemma-lisse-etale}.
\end{enumerate}
\item Let $\mathcal{F}$ be an $\mathcal{O}_\mathcal{X}$-module on
$\mathcal{X}_{fppf}$. The following are equivalent
\begin{enumerate}
\item $\mathcal{F}$ is parasitic, and
\item $g^*\mathcal{F} = 0$ where
$g :  \Sh(\mathcal{X}_{flat,fppf}) \to \Sh(\mathcal{X}_{fppf})$
is as in Lemma \ref{lemma-lisse-etale}.
\end{enumerate}
\end{enumerate}
